import { beforeEach, describe, expect, it, vi } from 'vitest'
import { renderToStaticMarkup } from 'react-dom/server'
import { getSession } from '@/app/lib/auth'
import AdminPage from './page'

vi.mock('@/app/lib/auth', () => ({ getSession: vi.fn() }))
vi.mock('next/server', () => ({ connection: vi.fn() }))
vi.mock('next/navigation', () => ({
  forbidden: () => { throw new Error('NEXT_HTTP_ERROR_FALLBACK;403') },
}))

describe('admin page authorization', () => {
  beforeEach(() => vi.resetAllMocks())

  it('renders the dashboard for an admin', async () => {
    vi.mocked(getSession).mockResolvedValue({ userId: '1', role: 'admin', name: 'Alex' })

    const html = renderToStaticMarkup(await AdminPage())
    expect(html).toContain('Admin Dashboard')
    expect(html).toContain('Welcome, Alex.')
  })

  it.each([
    ['a non-admin', { userId: '2', role: 'user' as const, name: 'John' }],
    ['a missing session', null],
  ])('forbids %s', async (_description, session) => {
    vi.mocked(getSession).mockResolvedValue(session)

    await expect(AdminPage()).rejects.toThrow('NEXT_HTTP_ERROR_FALLBACK;403')
  })
})
EOF
npx vitest run app/admin/page.test.tsx"
